B='42d32a5294365a4aa4d5aa2b5f11729e147cb44324f4535065047e946e7b3a2a';N=datetime.datetime.now(datetime.timezone.utc).isoformat();RUNGS=['line','expanded-context','section-header','book-title','tei-header','parallel-passage']
def occ(rel,kw,label,note,ctx=[]):
 v=zc.verify(rel,kw);assert v['ok'],(rel,kw,v);note=f'{note} The compiler narrates or documents the headword-bearing act, speech, or heading; the represented actor is {label}. Source text ({zc.title(rel)}).'
 return {'RelPath':rel,'FromLb':v['fromLb'],'ToLb':v['toLb'],'Kwic':kw,'Curated':True,'AttributionNote':note,'ContextMasters':ctx,'ActorAttribution':{'Status':'narrated','Kind':'compiler narration or documentary heading','ActorLabel':'the compiler-narrator of '+zc.title(rel),'ActorRole':'compiler','RungsChecked':RUNGS,'GrammarEvidence':note,'ReviewedBy':'Codex f003 Lane B full-turn author','ReviewedUtc':N},'DraftActorProof':{'GrammaticalSubject':label,'FullCaseDecision':note}}
def named(rel,kw,name,note,ctx=None):
 v=zc.verify(rel,kw);assert v['ok'],(rel,kw,v);note=f'{note} {name} owns the complete headword-bearing turn. Source text ({zc.title(rel)}).'
 return {'RelPath':rel,'FromLb':v['fromLb'],'ToLb':v['toLb'],'Kwic':kw,'Curated':True,'MasterName':name,'AttributionNote':note,'ContextMasters':ctx or [{'MasterName':name,'Roles':['utterer','record-owner']}],'DraftActorProof':{'ExactHeadwordClause':kw,'SpeechFrame':note,'FullCaseDecision':name+' owns the complete headword-bearing turn.'}}
def build(id,ordinal,term,pt,alts,aliases,note,O,opening,body,zen,limit,related,masters,works,split='one-thing'):
 D=R/f'fresh-build/entries/{id}';D.mkdir(parents=True,exist_ok=True)
 S={'SenseKey':None,'MasterName':None,'PreferredTarget':pt,'AlternateTargets':alts,'SearchAliases':aliases,'Status':'preferred','Validation':'multi-source','Note':note,'Occurrences':O,'ClaimAnchors':[],'SourceTexts':[o['RelPath'] for o in O],'RelatedMasters':masters,'RelatedTerms':related,'ExplanationParts':{'CorpusEarnedOpening':opening,'EvidenceBody':[body]},'DraftEvidence':{'OpeningClaimEvidenceKeys':[f'o{i}' for i in range(1,len(O)+1)],'ZenBend':zen,'CounterexampleOrLimit':limit,'DifferentThingTest':{'Decision':split,'ComparedThings':[pt,'the same referent across the stored constructions'],'Reason':'The evidence changes predicate, stance, or grammatical setting without establishing a second lexical thing.'},'AliasRationale':'Aliases cover natural English lookup without adding an unproved interpretation.','ModifierControls':[{'finding':'checked','reason':'Longer compounds and named formulas are described where used and do not silently redefine an unsupported modifier.'}],'FamilyControls':[{'finding':'checked','reason':'Nearby family expressions are named in RelatedTerms and do not buy unmarked headword depth.'}],'IndependentWorkIds':works}}
 E={'Id':id,'SourceTerm':term,'CorpusBaselineSha256':B,'CreatedBy':'Codex f003 Lane B evidence-first','WrittenUtc':N,'Senses':[S]};W=D/'evidence.draft.json';W.write_text(json.dumps({'SchemaVersion':1,'Entry':E},ensure_ascii=False,indent=2)+'\n');(D/'WORK.md').write_text(f'# {term} — f003 Lane B ordinal {ordinal}\n\nstatus: drafted\nreferent: {pt}.\nactor guard: full headword-bearing turn adjudicated before speaker assignment.\nlookup probes: '+ '; '.join(aliases[:5])+'.\n');subprocess.run([sys.executable,str(R/'compile_evidence_draft.py'),str(W),'--output',str(D/'entry.v2.json'),'--report',str(D/'compile-report.json')],check=True);(D/'STATUS').write_text('drafted\n');return {'ordinal':ordinal,'term':term,'worksheetSha256':hashlib.sha256(W.read_bytes()).hexdigest(),'entrySha256':hashlib.sha256((D/'entry.v2.json').read_bytes()).hexdigest()}

